SELECT
cycle_products.id AS id,
cycle_products.date AS date,
(SELECT CONCAT(first_name, ' ', last_name) FROM users WHERE id = cycle_products.created_by) AS createBy,
cycle_products.reference AS reference,
(SELECT name FROM companies WHERE id = cycle_products.company_id) AS companyName,
(SELECT name FROM location_groups WHERE id = cycle_products.location_group_id) AS warehouseName,
(SELECT CONCAT(account_codes, " · ", account_description) FROM chart_accounts WHERE id = cycle_products.deposit_to) AS account
FROM cycle_products
LEFT JOIN cycle_product_details ON cycle_products.id = cycle_product_details.product_id
WHERE cycle_products.status > 0 AND cycle_products.cp_type = 1
AND cycle_products.company_id IN (SELECT company_id FROM user_companies WHERE user_id = #{userId})

    AND cycle_products.date >= #{filter.dateFrom}


    AND cycle_products.date  <=  #{filter.dateTo}


    AND cycle_products.company_id= #{filter.companyId}


    AND cycle_products.location_group_id = #{filter.locationGroupId}


    AND cycle_product_details.product_id = #{filter.productId}


    AND cycle_products.created_by = #{filter.createdBy}

ORDER BY


        ${filter.orderBy}


        cycle_products.reference ASC



    LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT IFNULL(products.parent_id, null) AS parentId, CASE WHEN products.parent_id IS NULL THEN 'No Parent' ELSE CONCAT_WS(' ', parents.code, parents.name) END AS parentName, SUM(cycle_product_details.qty_difference) AS qty, SUM((IFNULL(cost,0) / products.small_val_uom) * qty_difference) AS totalCost FROM cycle_products INNER JOIN cycle_product_details ON cycle_products.id = cycle_product_details.cycle_product_id INNER JOIN inventory_valuations ON inventory_valuations.cycle_product_id = cycle_products.id AND inventory_valuations.pid = cycle_product_details.product_id INNER JOIN users ON users.id = cycle_products.created_by INNER JOIN locations ON cycle_product_details.location_id = locations.id INNER JOIN products ON products.id = cycle_product_details.product_id LEFT JOIN products AS parents ON parents.id = products.parent_id WHERE cycle_products.company_id IN (SELECT company_id FROM user_companies WHERE user_id = #{userId}) AND cycle_products.status > 0
AND cycle_products.date >= #{filter.dateFrom}
AND cycle_products.date <= #{filter.dateTo}
AND cycle_products.location_group_id = #{filter.warehouseId}
AND products.parent_id = #{filter.productId}
AND cycle_products.modified_by = #{filter.approvedBy}
GROUP BY products.parent_id ORDER BY cycle_products.date
LIMIT #{filter.page}, #{filter.rowsPerPage}

