SELECT COALESCE(SUM(totalCost), 0) as grandTotal FROM (
    SELECT
    (cycle_product_details.qty_difference / products.small_val_uom) AS qty,
    IFNULL(cost,0) / products.small_val_uom AS unitCost,
    SUM((IFNULL(cost,0) / products.small_val_uom) * qty_difference) AS totalCost
    FROM cycle_products
    INNER JOIN cycle_product_details ON cycle_products.id = cycle_product_details.cycle_product_id
    INNER JOIN inventory_valuations ON inventory_valuations.cycle_product_id = cycle_products.id AND inventory_valuations.pid = cycle_product_details.product_id
    INNER JOIN users ON users.id = cycle_products.created_by
    INNER JOIN locations ON cycle_product_details.location_id = locations.id
    INNER JOIN products ON products.id = cycle_product_details.product_id
    WHERE cycle_products.company_id IN (SELECT company_id FROM user_companies WHERE user_id = #{userId})
    AND cycle_products.status > 0

        AND cycle_products.date >= #{filter.dateFrom}


        AND cycle_products.date <= #{filter.dateTo}


        AND cycle_products.location_group_id = #{filter.warehouseId}


        AND cycle_product_details.product_id = #{filter.productId}


        AND cycle_products.modified_by = #{filter.approvedBy}

) as subquery

SELECT p.parent_id AS parentId, IFNULL((SELECT CONCAT_WS(' ',code,'-',name) FROM products WHERE id=(SELECT parent_id FROM products WHERE id=p.id)), 'No Parent') AS parentName FROM `inventories` INNER JOIN products AS p ON p.id = `inventories`.`product_id` WHERE p.is_active = 1 AND inventories.is_active = 1
AND location_group_id = #{filter.warehouseId}
AND p.id IN (SELECT product_id FROM product_pgroups WHERE pgroup_id = #{filter.productGroupId})
AND p.id IN (SELECT product_prices.product_id FROM product_prices WHERE price_type_id = #{filter.productPriceListId} AND product_prices.product_id = `inventories`.`product_id`)
AND p.id = #{filter.productId}
AND (p.code LIKE CONCAT("%", #{filter.searchText}, "%") OR p.barcode LIKE CONCAT("%", #{filter.searchText}, "%") OR p.name LIKE CONCAT("%", #{filter.searchText}, "%"))
GROUP BY parentName
LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT p.id AS productId, IFNULL(p.code, '') AS code, IFNULL(p.barcode, '') AS upc, IFNULL(p.name, '') AS productName, (CASE WHEN p.small_val_uom = 1 THEN ( SELECT abbr FROM uoms WHERE id = p.price_uom_id ) ELSE ( SELECT abbr FROM uoms WHERE id IN ( SELECT to_uom_id FROM uom_conversions WHERE is_active = 1 AND from_uom_id = p.price_uom_id AND is_small_uom = 1 ) ) END) AS uom, ( SUM(inventories.qty) - IFNULL(( SELECT SUM(total_order) FROM ${tableName} WHERE ${tableName}.product_id = inventories.product_id GROUP BY ${tableName}.product_id ), 0) ) AS totalQtyAvailable FROM `inventories` INNER JOIN products AS p ON p.id = `inventories`.`product_id` WHERE p.is_active = 1 AND inventories.is_active = 1
AND p.parent_id = #{parentId}
AND p.parent_id IS NULL
AND location_group_id = #{filter.warehouseId}
AND p.id IN (SELECT product_id FROM product_pgroups WHERE pgroup_id = #{filter.productGroupId})
AND p.id IN (SELECT product_prices.product_id FROM product_prices WHERE price_type_id = #{filter.productPriceListId} AND product_prices.product_id = `inventories`.`product_id`)
AND p.id = #{filter.productId}
GROUP BY `product_id` HAVING totalQtyAvailable > 0 ORDER BY p.code ASC

SELECT COUNT(p.id) FROM products p INNER JOIN ( SELECT product_id, SUM(qty) AS total_qty FROM inventories WHERE is_active = 1
AND `date` <= #{filter.dateTo}
AND location_group_id = #{filter.warehouseId}
AND location_id = #{filter.locationId}
GROUP BY product_id ) i ON i.product_id = p.id WHERE p.is_active IN (1,8) AND p.is_packet = 0 AND p.id IN (SELECT parent_id FROM products WHERE is_active = 1 GROUP BY parent_id)
AND IFNULL(i.total_qty, 0) > 0
AND IFNULL(i.total_qty, 0) = 0

SELECT p.id AS parentId, IFNULL(( SELECT SUM(qty) FROM inventories INNER JOIN products ON inventories.product_id = products.id WHERE inventories.is_active = 1 AND products.is_active = 1 AND products.parent_id = p.id
AND `date` <= #{filter.dateTo}
AND location_group_id = #{filter.warehouseId}
AND location_id = #{filter.locationId}
), 0) AS endingQty, p.name AS parentName FROM products p WHERE p.is_active IN (1,8) AND p.is_packet = 0 AND p.id IN (SELECT parent_id FROM products WHERE is_active = 1 AND parent_id IS NOT NULL GROUP BY parent_id)
HAVING endingQty > 0
HAVING endingQty = 0
ORDER BY parent_id ASC, p.code ASC

SELECT p.id AS id, p.name AS name, p.code AS code, p.barcode AS upc, (CASE WHEN p.small_val_uom = 1 THEN ( SELECT abbr FROM uoms WHERE id = p.price_uom_id ) ELSE ( SELECT abbr FROM uoms WHERE id IN ( SELECT to_uom_id FROM uom_conversions WHERE is_active = 1 AND from_uom_id = p.price_uom_id AND is_small_uom = 1 ) ) END) AS uom, IFNULL(p.unit_cost, 0) AS lastCost, IFNULL(( SELECT SUM(qty) FROM inventories WHERE is_active = 1 AND product_id = p.id
AND `date` < #{filter.dateFrom}
AND location_group_id = #{filter.warehouseId}
AND location_id = #{filter.locationId}
), 0) AS beginningQty, IFNULL(( SELECT SUM(qty) FROM inventories WHERE is_active = 1 AND product_id = p.id
AND `date` <= #{filter.dateTo}
AND location_group_id = #{filter.warehouseId}
AND location_id = #{filter.locationId}
), 0) AS endingQty, IFNULL(( SELECT SUM(total_order) FROM
`${filter.warehouseId}_group_totals`
`inventory_totals`
WHERE product_id = p.id ), 0) AS qtyOrder, p.is_not_for_sale AS isForSale FROM products p WHERE p.is_active IN (1, 8) AND p.is_packet = 0 AND p.parent_id = #{parentId} AND EXISTS ( SELECT 1 FROM inventories inv WHERE inv.product_id = p.id AND inv.is_active = 1
AND inv.`date` <= #{filter.dateTo}
AND inv.location_group_id = #{filter.warehouseId}
AND inv.location_id = #{filter.locationId}
)
AND p.id IN (SELECT product_id FROM product_pgroups WHERE pgroup_id = #{filter.productGroupId})
AND p.id = #{filter.productId}
AND p.unit_cost > 0
AND p.unit_cost > 0
HAVING endingQty > 0
HAVING endingQty = 0
ORDER BY parent_id ASC, p.code ASC

SELECT SUM(
COALESCE((
SELECT SUM(qty)
FROM inventories i
WHERE i.is_active = 1
AND i.product_id = p.id

    AND i.date <= #{filter.dateTo}


    AND i.location_group_id = #{filter.warehouseId}


    AND i.location_id = #{filter.locationId}

), 0) -
COALESCE((
SELECT SUM(total_order)
FROM


        ${filter.warehouseId}_group_totals


        inventory_totals

 t
WHERE t.product_id = p.id
), 0)
) AS grandTotal
FROM products p
WHERE p.is_active IN (1, 8)
AND p.is_packet = 0
AND EXISTS (
    SELECT 1 FROM inventories inv
    WHERE inv.product_id = p.id
      AND inv.is_active = 1

      AND inv.date <= #{filter.dateTo}


      AND inv.location_group_id = #{filter.warehouseId}


      AND inv.location_id = #{filter.locationId}

)

    AND p.id IN (
    SELECT product_id
    FROM product_pgroups
    WHERE pgroup_id = #{filter.productGroupId}
    )


    AND p.id = #{filter.productId}


    AND p.unit_cost > 0




            HAVING grandTotal > 0


            HAVING grandTotal = 0

