SELECT p.id AS productId, p.code AS sku, p.barcode AS upc, p.name AS productName, p.price_uom_id AS uomId, uoms.abbr AS uom, p.unit_cost AS unitCost FROM products p INNER JOIN uoms ON uoms.id = p.price_uom_id
ORDER BY
${filter.orderBy}
p.code ASC
LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT COUNT(inventory_valuations.id) FROM inventory_valuations INNER JOIN products ON products.id = inventory_valuations.pid INNER JOIN uoms ON uoms.id = products.price_uom_id WHERE inventory_valuations.is_active = 1
AND inventory_valuations.date <= #{filter.date}
AND inventory_valuations.pid = #{filter.productId}

SELECT inventory_valuations.pid AS productId, IFNULL(inventory_valuations.on_hand_small,0) AS onHand, IFNULL(SUM(inventory_valuations.small_qty),0) AS qty, IFNULL(AVG(inventory_valuations.avg_cost),0) AS avgCost, IFNULL(inventory_valuations.asset_value,0) AS assetValue, CONCAT_WS(' ', products.code, products.name) AS productName, COALESCE( (SELECT uoms.name FROM uoms WHERE uoms.id IN ( SELECT uom_conversions.to_uom_id FROM uom_conversions WHERE uom_conversions.from_uom_id = products.price_uom_id AND uom_conversions.is_small_uom = 1 AND uom_conversions.is_active = 1 )), (SELECT uoms.name FROM uoms WHERE uoms.id = products.price_uom_id) ) AS uom FROM inventory_valuations INNER JOIN products ON products.id = inventory_valuations.pid WHERE inventory_valuations.is_active = 1
AND inventory_valuations.date <= #{filter.date}
AND inventory_valuations.pid = #{filter.productId}
GROUP BY inventory_valuations.pid ORDER BY inventory_valuations.date, inventory_valuations.purchase_order_id
LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT COUNT(inventory_valuations.pid)
FROM inventory_valuations
WHERE inventory_valuations.is_active = 1

    AND inventory_valuations.date <= #{filter.date}


    AND inventory_valuations.pid = #{filter.productId}

SELECT inventory_valuations.pid AS productId, CONCAT_WS(' ', products.code, products.name) AS productName FROM inventory_valuations INNER JOIN products ON products.id = inventory_valuations.pid WHERE inventory_valuations.is_active = 1
AND inventory_valuations.date <= #{filter.date}
AND inventory_valuations.pid = #{filter.productId}
GROUP BY products.id, products.code, products.name ORDER BY inventory_valuations.date, inventory_valuations.purchase_order_id
LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT SUM(IFNULL(inventory_valuations.qty, 0))
FROM inventory_valuations
INNER JOIN products ON products.id = inventory_valuations.pid
WHERE inventory_valuations.is_active = 1

    AND inventory_valuations.date <= #{filter.date}


    AND inventory_valuations.pid = #{filter.productId}

SELECT SUM(IFNULL(inventory_valuations.qty, 0) * IFNULL(inventory_valuations.avg_cost, 0))
FROM inventory_valuations
INNER JOIN products ON products.id = inventory_valuations.pid
WHERE inventory_valuations.is_active = 1

    AND inventory_valuations.date <= #{filter.date}


    AND inventory_valuations.pid = #{filter.productId}

SELECT COUNT(pr.id)
FROM price_requests AS pr
INNER JOIN users AS u ON u.id = pr.created_by
INNER JOIN employees AS e ON e.user_id = u.id
WHERE pr.status = 2

    AND DATE(pr.closed) >= #{filter.dateFrom}


    AND DATE(pr.closed) <= #{filter.dateTo}


    AND pr.created_by = #{filter.createdBy}

SELECT
pr.created_by AS createdBy,
e.id AS employeeId,
e.name AS employeeName
FROM price_requests AS pr
INNER JOIN users AS u ON u.id = pr.created_by
INNER JOIN employees AS e ON e.user_id = u.id
WHERE pr.status = 2

    AND DATE(pr.closed) >= #{filter.dateFrom}


    AND DATE(pr.closed) <= #{filter.dateTo}


    AND pr.created_by = #{filter.createdBy}

GROUP BY pr.created_by

    LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT pr.product_id AS productId, p.name AS productName, p.code AS productCode, IFNULL((SELECT name FROM pgroups WHERE id = (SELECT pgroup_id FROM product_pgroups WHERE product_id = p.id LIMIT 1) LIMIT 1), 'N/A') AS productBrand, IFNULL(pr.request_code, 0) AS priceRequestCode, IFNULL(pr.request_date, 0) AS priceRequestDate FROM price_requests AS pr INNER JOIN users AS u ON u.id = pr.created_by INNER JOIN products AS p ON pr.product_id = p.id WHERE pr.status = 2 AND pr.created_by = #{createdBy}
AND DATE(pr.closed) >= #{filter.dateFrom}
AND DATE(pr.closed) <= #{filter.dateTo}
ORDER BY pr.created_by

SELECT qd.product_id AS productId, p.name AS productName, p.code AS productCode, IFNULL((SELECT name FROM pgroups WHERE id = (SELECT pgroup_id FROM product_pgroups WHERE product_id = p.id LIMIT 1) LIMIT 1), 'N/A') AS productBrand, IFNULL(q.quotation_code, 0) AS quotationCode, IFNULL(q.quotation_date, 0) AS quotationDate FROM quotations AS q LEFT JOIN quotation_details AS qd ON qd.quotation_id = q.id INNER JOIN users AS u ON u.id = q.created_by INNER JOIN products AS p ON qd.product_id = p.id WHERE q.status = 2 AND q.created_by = #{createdBy}
AND DATE(q.quotation_date) >= #{filter.dateFrom}
AND DATE(q.quotation_date) <= #{filter.dateTo}
ORDER BY q.created_by

SELECT od.product_id AS productId, p.name AS productName, p.code AS productCode, IFNULL((SELECT name FROM pgroups WHERE id = (SELECT pgroup_id FROM product_pgroups WHERE product_id = p.id LIMIT 1) LIMIT 1), 'N/A') AS productBrand, IFNULL(o.status, 0) AS saleOrderStatus, IFNULL(o.order_code, 0) AS saleOrderCode, IFNULL(o.order_date, 0) AS saleOrderDate FROM orders AS o LEFT JOIN order_details AS od ON od.order_id = o.id INNER JOIN users AS u ON u.id = o.created_by INNER JOIN products AS p ON od.product_id = p.id WHERE o.status = 2 AND o.created_by = #{createdBy}
AND o.order_date >= #{filter.dateFrom}
AND o.order_date <= #{filter.dateTo}
ORDER BY o.created_by

