SELECT IFNULL(p.parent_id, 0) AS itemId, CASE WHEN p.parent_id IS NULL THEN 'No Parent' ELSE (SELECT CONCAT_WS(' ',code,'-',name) FROM products WHERE id = p.parent_id) END AS itemName, SUM(inv.qty) AS qty FROM inventories inv INNER JOIN products p ON p.id = inv.product_id
AND p.parent_id IS NOT NULL
LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT IFNULL(p.parent_id, 0) AS itemId, CASE WHEN p.parent_id IS NULL THEN 'No Parent' ELSE (SELECT CONCAT_WS(' ',code,'-',name) FROM products WHERE id = p.parent_id) END AS itemName, SUM(inv.qty) AS qty FROM inventories inv INNER JOIN products p ON p.id = inv.product_id
AND p.parent_id IS NULL
LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT p.id AS itemId, p.name AS itemName FROM inventories inv INNER JOIN products p ON p.id = inv.product_id
GROUP BY p.id
LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT IFNULL(p.parent_id, null) AS itemId, CASE WHEN p.parent_id IS NULL THEN 'No Parent' ELSE (SELECT CONCAT_WS(' ',code,'-',name) FROM products WHERE id = p.parent_id) END AS itemName FROM inventories inv INNER JOIN products p ON p.id = inv.product_id
GROUP BY p.parent_id
LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT
p.code AS code,
p.name AS `productName`,
COALESCE(
(
SELECT SUM(inv_begin.qty)
FROM inventories inv_begin
WHERE inv_begin.product_id = p.id
AND inv_begin.is_active = 1

    AND inv_begin.date < #{filter.dateFrom}


    AND inv_begin.location_group_id = #{filter.warehouseId}


    AND inv_begin.location_id = #{filter.locationId}

), 0) AS beginning,
COALESCE(
(
SELECT SUM(inv_inout.qty)
FROM inventories inv_inout
WHERE inv_inout.product_id = p.id
AND inv_inout.is_active = 1

    AND inv_inout.date >= #{filter.dateFrom}


    AND inv_inout.date <= #{filter.dateTo}


    AND inv_inout.location_group_id = #{filter.warehouseId}


    AND inv_inout.location_id = #{filter.locationId}


    AND inv_inout.type = #{filter.productTypeId}

), 0) AS `inOutAmount`,
COALESCE(
(
SELECT SUM(inv_ending.qty)
FROM inventories inv_ending
WHERE inv_ending.product_id = p.id
AND inv_ending.is_active = 1

    AND inv_ending.location_group_id = #{filter.warehouseId}


    AND inv_ending.location_id = #{filter.locationId}


    AND inv_ending.type = #{filter.productTypeId}

), 0) AS ending,
(CASE
WHEN p.small_val_uom = 1 THEN (
SELECT abbr
FROM uoms
WHERE id = p.price_uom_id
)
ELSE (
SELECT abbr
FROM uoms
WHERE id IN (
SELECT to_uom_id
FROM uom_conversions
WHERE is_active = 1
AND from_uom_id = p.price_uom_id
AND is_small_uom = 1
)
)
END) AS uomName
FROM inventories inv
INNER JOIN products p ON p.id = inv.product_id
WHERE inv.is_active = 1

    AND inv.date >= #{filter.dateFrom}


    AND inv.date <= #{filter.dateTo}


    AND inv.location_group_id = #{filter.warehouseId}


