IFNULL( SUM(CASE WHEN inv.is_active = 1 AND inv.product_id = #{productId} AND inv.purchase_return_id IS NOT NULL THEN inv.qty END), 0) AS br,
IFNULL( SUM(CASE WHEN inv.is_active = 1 AND inv.product_id = #{productId} AND inv.transfer_order_id IS NOT NULL THEN inv.qty END), 0) AS transfer,
IFNULL((SELECT SUM(total_order) FROM inventory_totals WHERE inventory_totals.product_id = p.id), 0) AS totalOrder FROM inventories inv INNER JOIN products p ON p.id = inv.product_id INNER JOIN locations l ON l.id = inv.location_id
